        assert!(!RetryError::Permanent(String::new()).is_transient());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_preserves_signature() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 7,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        if calls == 3 {
            Ok(())
        } else {
            Err(RetryError::Transient("unavailable".to_owned()))
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![7, 14]);
}

