use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_saturates_delay() {
    let config = RetryConfig {
        max_attempts: 4,
        base_delay_ms: 10,
        max_delay_ms: 25,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Transient("temporary".to_owned()))
    });

    assert_eq!(calls, 4);
    assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    assert_eq!(result, Err(RetryError::Transient("temporary".to_owned())));
}

#[test]
fn public_api_returns_permanent_failure_without_retrying() {
    let config = RetryConfig {
        max_attempts: 5,
        base_delay_ms: 10,
        max_delay_ms: 100,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;

    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("invalid input".to_owned()))
    });

    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
    assert_eq!(result, Err(RetryError::Permanent("invalid input".to_owned())));
}

